using Antlr4.Runtime;using Antlr4.Runtime.Tree;using SpreadsheetApp.Service;namespace SpreadsheetApp.Services{    public class ExpressionEngine    {        /// <param name="expression">Вираз без початкового «=».</param>        /// <param name="sheet">Таблиця, з якої беруться значення клітинок-посилань.</param>        /// <exception cref="ExpressionException">Синтаксична помилка або помилка обчислення.</exception>        public object Evaluate(string expression, Spreadsheet sheet)        {            IParseTree tree = Parse(expression);            return new Evaluator(sheet).Visit(tree);        }        private IParseTree Parse(string expression)        {            if (string.IsNullOrWhiteSpace(expression))                throw new ExpressionException("Вираз порожній", 1);            var lexer = new LabCalculatorLexer(new AntlrInputStream(expression.ToLowerInvariant()));            var parser = new LabCalculatorParser(new CommonTokenStream(lexer));            parser.RemoveErrorListeners();            parser.AddErrorListener(new ThrowExceptionErrorListener());            return parser.compileUnit();        }    }}